  const issuance = await client.request({ command: "ledger_entry", mpt_issuance: issuanceId });
  console.log("Issuance node:", JSON.stringify(issuance.result.node, null, 2));

  for (const [label, addr] of Object.entries(holders)) {
    try {
      const r = await client.request({
        command: "ledger_entry",
        mptoken: { mpt_issuance_id: issuanceId, account: addr },
      });
      console.log(`${label} (${addr}):`, JSON.stringify(r.result.node, null, 2));
    } catch (err) {
      console.log(`${label} (${addr}): no MPToken object / error`, (err as Error).message);
    }
  }

  await client.disconnect();
}
main();
